1	use anyhow::Result;
2	use std::path::Path;
3	
4	use crate::paths;
5	
6	pub fn install(global: bool) -> Result<()> {
7	    let claude_dir = paths::claude_hooks_dir();
8	    let settings_path = if global {
9	        claude_dir.join("settings.json")
10	    } else {
11	        Path::new(".claude").join("settings.json")
12	    };
13	
14	    let codeflow_bin = find_codeflow_binary();
15	
16	    check_rtk_conflict(&settings_path)?;
17	
18	    let settings = read_or_create_settings(&settings_path)?;
19	    let updated = inject_hooks(&settings, &codeflow_bin)?;
20	    write_settings(&settings_path, &updated)?;
21	
22	    let scope = if global { "global" } else { "project" };
23	    println!("✓ CODEFLOW hooks installed ({} scope)", scope);
24	    println!("  Settings: {}", settings_path.display());
25	    println!("  Binary: {}", codeflow_bin);
26	    println!();
27	    println!("Bash tool output will now be compressed automatically.");
28	    println!("Run `codeflow stats` to see your token savings.");
29	
30	    Ok(())
31	}
32	
33	pub fn uninstall(global: bool) -> Result<()> {
34	    let claude_dir = paths::claude_hooks_dir();
35	    let settings_path = if global {
36	        claude_dir.join("settings.json")
37	    } else {
38	        Path::new(".claude").join("settings.json")
39	    };
40	
41	    if !settings_path.exists() {
42	        println!("No settings file found at {}", settings_path.display());
43	        return Ok(());
44	    }
45	
46	    let settings = std::fs::read_to_string(&settings_path)?;
47	    let mut json: serde_json::Value = serde_json::from_str(&settings)?;
48	
49	    if let Some(hooks) = json.get_mut("hooks") {
50	        if let Some(obj) = hooks.as_object_mut() {
51	            obj.remove("PreToolUse");
52	            obj.remove("PostToolUse");
53	            if obj.is_empty() {
54	                json.as_object_mut().unwrap().remove("hooks");
55	            }
56	        }
57	    }
58	
59	    let output = serde_json::to_string_pretty(&json)?;
60	    std::fs::write(&settings_path, output)?;
61	    println!("✓ CODEFLOW hooks removed from {}", settings_path.display());
62	
63	    Ok(())
64	}
65	
66	fn find_codeflow_binary() -> String {
67	    std::env::current_exe()
68	        .map(|p| p.to_string_lossy().to_string())
69	        .unwrap_or_else(|_| "codeflow".to_string())
70	}
71	
72	fn check_rtk_conflict(settings_path: &Path) -> Result<()> {
73	    if !settings_path.exists() {
74	        return Ok(());
75	    }
76	    let content = std::fs::read_to_string(settings_path)?;
77	    if content.contains("rtk") || content.contains("RTK") {
78	        eprintln!("⚠ Warning: Existing RTK hooks detected in {}", settings_path.display());
79	        eprintln!("  CODEFLOW will override RTK hooks. Remove RTK hooks manually if needed.");
80	    }
81	    Ok(())
82	}
83	
84	fn read_or_create_settings(path: &Path) -> Result<String> {
85	    if path.exists() {
86	        Ok(std::fs::read_to_string(path)?)
87	    } else {
88	        Ok("{}".to_string())
89	    }
90	}
91	
92	fn inject_hooks(settings_json: &str, codeflow_bin: &str) -> Result<String> {
93	    let mut json: serde_json::Value = serde_json::from_str(settings_json)?;
94	
95	    let bin_escaped = codeflow_bin.replace('\\', "\\\\");
96	
97	    let hooks = serde_json::json!({
98	        "PreToolUse": [
99	            {
100	                "matcher": "Bash",
101	                "hooks": [
102	                    {
103	                        "type": "command",
104	                        "command": format!(
105	                            "{} hook pre-tool-use",
106	                            bin_escaped
107	                        )
108	                    }
109	                ]
110	            }
111	        ],
112	        "PostToolUse": [
113	            {
114	                "matcher": "Bash",
115	                "hooks": [
116	                    {
117	                        "type": "command",
118	                        "command": format!(
119	                            "{} hook post-tool-use",
120	                            bin_escaped
121	                        )
122	                    }
123	                ]
124	            }
125	        ]
126	    });
127	
128	    if let Some(existing) = json.get_mut("hooks").and_then(|h| h.as_object_mut()) {
129	        existing.insert("PreToolUse".to_string(), hooks["PreToolUse"].clone());
130	        existing.insert("PostToolUse".to_string(), hooks["PostToolUse"].clone());
131	    } else {
132	        json["hooks"] = hooks;
133	    }
134	
135	    Ok(serde_json::to_string_pretty(&json)?)
136	}
137	
138	fn write_settings(path: &Path, content: &str) -> Result<()> {
139	    if let Some(parent) = path.parent() {
